<?php
declare(strict_types=1);
/* Halaman perangkat desa (Wilayah Rawan) dan mahasiswa/peneliti (Parameter, Matriks, Oseanografi, Hasil, Simulasi). */

/* ---------------- Wilayah rawan (perangkat desa) ---------------- */
function rawan_rows(): array { $r = array_values(array_filter(wil_rows(), fn($x) => $x['inf'])); usort($r, fn($a, $b) => [$b['inf']['skor'], $b['w']['jumlah_kk']] <=> [$a['inf']['skor'], $a['w']['jumlah_kk']]); foreach ($r as $i => &$x) $x['rank'] = $i + 1; return $r; }
function pg_wilayah_rawan(): array {
    if (gv('unduh') === 'csv') { $rows = [['Peringkat', 'Wilayah', 'Tipe', 'Jumlah KK (sensus)', 'Skor', 'Tingkat', 'Faktor dominan', 'Tanggal analisis']]; foreach (rawan_rows() as $r) $rows[] = [$r['rank'], $r['w']['nama_wilayah'], $r['w']['tipe'], $r['w']['jumlah_kk'], $r['inf']['skor'], $r['inf']['tingkat']['nama_tingkat'], implode('; ', array_map(fn($d) => $d['p']['nama_parameter'] . ' ' . nfa($d['nilai']) . ' ' . $d['p']['satuan'], drivers($r['w']['id_wilayah'], 2))), $r['inf']['hasil']['tanggal_analisis']]; send_csv('wilayah-rawan-pulo-panjang.csv', $rows); }
    $d = array_reverse(distribusi()); $cards = ''; foreach ($d as $x) $cards .= '<div class="lvl-card" style="--c:' . e($x['t']['warna']) . '">' . lvl_icon(rank_of($x['t']['id_tingkat']), 24) . '<b style="font-size:17px">' . e($x['t']['nama_tingkat']) . ': ' . count($x['rows']) . ' wilayah</b><p>sekitar ' . nf(sum(array_map(fn($r) => $r['w']['jumlah_kk'] ?? 0, $x['rows']))) . ' kepala keluarga (estimasi), rentang skor ' . nf($x['t']['skor_min'], 2) . ' sampai ' . nf($x['t']['skor_maks'], 2) . '.</p></div>';
    $cfg = ['id' => 'rw', 'page' => 'wilayah-rawan', 'rows' => 'rawan_rows', 'pageSize' => 10, 'search' => fn($r) => $r['w']['nama_wilayah'] . ' ' . $r['w']['tipe'], 'search_ph' => 'Cari wilayah', 'readonly' => true,
        'filters' => [['k' => 't', 'l' => 'Tingkat', 'opts' => array_map(fn($t) => [$t['id_tingkat'], $t['nama_tingkat']], tingkat_list()), 'test' => fn($r, $v) => (string) $r['inf']['tingkat']['id_tingkat'] === $v]],
        'toolbar' => '<a class="btn" href="' . e(url('wilayah-rawan', ['unduh' => 'csv'])) . '">' . ic('download', 18) . 'Unduh CSV</a>',
        'columns' => [['k' => 'rank', 'l' => 'Peringkat', 'cls' => 'c', 'v' => fn($r) => $r['rank'], 'f' => fn($r) => '<b class="num">' . $r['rank'] . '</b>'], ['k' => 'w', 'l' => 'Wilayah', 'v' => fn($r) => $r['w']['nama_wilayah'], 'f' => fn($r) => '<b>' . e($r['w']['nama_wilayah']) . '</b><span class="sub">' . e($r['w']['tipe']) . '</span>'], ['k' => 'kk', 'l' => 'KK (estimasi)', 'cls' => 'r', 'v' => fn($r) => $r['w']['jumlah_kk'] ?? 0, 'f' => fn($r) => '<span class="num">' . nf($r['w']['jumlah_kk']) . '</span>'], ['k' => 'skor', 'l' => 'Skor', 'v' => fn($r) => $r['inf']['skor'], 'f' => fn($r) => skor_bar((float) $r['inf']['skor'], $r['inf']['tingkat']['warna'] ?? null)], ['k' => 't', 'l' => 'Tingkat', 'v' => fn($r) => $r['inf']['skor'], 'f' => fn($r) => tingkat_tag($r['inf']['tingkat'])], ['k' => 'f', 'l' => 'Faktor dominan', 'cls' => 'wrap', 'f' => fn($r) => '<div style="display:flex;gap:6px;flex-wrap:wrap">' . implode('', array_map('driver_chip', drivers($r['w']['id_wilayah'], 2))) . '</div>']]];
    return ['title' => 'Wilayah Rawan', 'html' => page_head('Wilayah Rawan', 'Daftar wilayah diurutkan dari skor kerawanan tertinggi untuk mendukung penentuan prioritas kesiapsiagaan.') . '<div class="grid g3" style="margin-bottom:18px">' . $cards . '</div>' . table_list($cfg)];
}

/* ---------------- Parameter dan pembobotan ---------------- */
function pg_parameter(): array {
    if (user_role() === 'admin') return parameter_admin();
    $ps = tbl('parameter'); $groups = uniq_list(array_column($ps, 'kelompok')); $tb = sum(array_column($ps, 'bobot')); $ts = tingkat_list();
    $h = page_head('Parameter dan Pembobotan', 'Dasar klasifikasi: parameter, bobot, dan kelas skor yang dipakai menghitung skor kerawanan.') . '<div class="grid g2" style="margin-bottom:18px"><div class="panel"><div class="panel-h"><h2>Rumus skor total</h2></div><div style="padding:16px;border-radius:12px;background:var(--surface-2);border:var(--bw) solid var(--line);font-family:var(--font-display);font-size:19px;line-height:1.6">Skor total = Σ (bobot × skor parameter) ÷ Σ bobot</div><p class="muted" style="margin-top:12px;font-size:14px">Total bobot saat ini <b class="num">' . nf($tb, 2) . '</b>. Parameter pendukung berbobot 0 tidak ikut dihitung, dipakai sebagai informasi dan validasi.</p></div><div class="panel"><div class="panel-h"><h2>Batas tingkat kerawanan</h2></div><div class="stack" style="gap:8px">' . implode('', array_map(fn($t) => '<div class="lvl-card" style="--c:' . e($t['warna']) . '">' . lvl_icon(rank_of($t['id_tingkat']), 20) . '<b>' . e($t['nama_tingkat']) . ': skor ' . nf($t['skor_min'], 2) . ' sampai ' . nf($t['skor_maks'], 2) . '</b><p>' . e($t['makna_warga']) . '</p></div>', $ts)) . '</div></div></div><div class="stack">';
    foreach ($groups as $g) { $gp = array_values(array_filter($ps, fn($p) => $p['kelompok'] === $g)); $col = KEL_COLOR[$g] ?? 'var(--primary)';
        $h .= '<div class="panel"><div class="panel-h"><h2 style="display:flex;align-items:center;gap:10px"><span class="dot" style="--c:' . $col . ';width:14px;height:14px"></span>' . e($g) . '</h2><span class="tag plain">Bobot kelompok ' . nf(sum(array_column($gp, 'bobot')) * 100, 0) . '%</span></div><div class="stack" style="gap:10px">';
        foreach ($gp as $p) { $ks = kelas_of($p['id_parameter']); $h .= '<details style="border:var(--bw) solid var(--line);border-radius:12px"><summary style="cursor:pointer;padding:12px 14px;display:grid;grid-template-columns:minmax(120px,1fr) 70px minmax(80px,160px);gap:12px;align-items:center;list-style:none"><span><b>' . e($p['nama_parameter']) . '</b><span class="faint" style="display:block;font-size:13px">Satuan: ' . e($p['satuan']) . '</span></span><span class="num" style="text-align:right;font-weight:700">' . nf($p['bobot'] * 100, 0) . '%</span><div class="prog" style="--c:' . $col . '"><i style="width:' . min(100, $p['bobot'] * 100 / 0.25) . '%"></i></div></summary><div class="tbl-wrap" style="border-top:1px solid var(--line)"><table class="tbl"><thead><tr><th>Rentang nilai (' . e($p['satuan']) . ')</th><th class="c">Skor</th></tr></thead><tbody>' . ($ks ? implode('', array_map(fn($k) => '<tr><td class="num">' . bound($k['batas_bawah']) . ' sampai kurang dari ' . bound($k['batas_atas']) . '</td><td class="c"><span class="tag plain">' . $k['skor'] . '</span></td></tr>', $ks)) : '<tr><td colspan="2" class="muted">Belum ada kelas skor.</td></tr>') . '</tbody></table></div></details>'; }
        $h .= '</div></div>'; }
    return ['title' => 'Parameter dan Pembobotan', 'html' => $h . '</div>'];
}

/* ---------------- Matriks data ---------------- */
function heat_style($skor, int $idParam): string {
    $ts = tingkat_list(); [$mn, $mx] = skor_bounds($idParam); $r = (int) clamp(round((($skor ?? $mn) - $mn) / (($mx - $mn) ?: 1) * (count($ts) - 1)), 0, count($ts) - 1);
    return 'background:color-mix(in srgb,' . e($ts[$r]['warna']) . ' 28%,var(--surface));border:var(--bw) solid color-mix(in srgb,' . e($ts[$r]['warna']) . ' 70%,transparent)';
}
function pg_matriks(): array {
    $ps = tbl('parameter'); $ws = tbl('wilayah'); $mode = gv('mode') === 'skor' ? 'skor' : 'nilai';
    if (gv('unduh') === 'csv') { $hdr = ['Wilayah']; foreach ($ps as $p) { $hdr[] = "{$p['nama_parameter']} ({$p['satuan']})"; $hdr[] = "Skor {$p['nama_parameter']}"; } $hdr[] = 'Skor total'; $hdr[] = 'Tingkat'; $rows = [$hdr]; foreach ($ws as $w) { $l = latest_data($w['id_wilayah']); $inf = info_wilayah($w['id_wilayah']); $r = [$w['nama_wilayah']]; foreach ($ps as $p) { $r[] = $l[$p['id_parameter']]['nilai'] ?? ''; $r[] = $l[$p['id_parameter']]['skor'] ?? ''; } $r[] = $inf['skor'] ?? ''; $r[] = $inf['tingkat']['nama_tingkat'] ?? ''; $rows[] = $r; } send_csv('matriks-data-kerawanan.csv', $rows); }
    $acts = seg([['nilai', 'Nilai'], ['skor', 'Skor']], $mode, fn($m) => url('matriks', ['mode' => $m]), 'Tampilan') . '<a class="btn" href="' . e(url('matriks', ['unduh' => 'csv'])) . '">' . ic('download', 18) . 'Unduh CSV</a>';
    $th = '<th style="position:sticky;left:0;z-index:2">Wilayah</th>'; foreach ($ps as $p) $th .= '<th class="c" title="' . e($p['nama_parameter']) . '">' . e($p['nama_parameter']) . '<span class="sub faint" style="font-weight:500">' . e($p['satuan']) . ($p['bobot'] ? ', ' . nf($p['bobot'] * 100, 0) . '%' : '') . '</span></th>'; $th .= '<th class="c">Skor total</th>';
    $tb = ''; foreach ($ws as $w) { $l = latest_data($w['id_wilayah']); $inf = info_wilayah($w['id_wilayah']); $tb .= '<tr><td style="position:sticky;left:0;background:var(--surface);font-weight:600;white-space:nowrap">' . e($w['nama_wilayah']) . '</td>'; foreach ($ps as $p) { $d = $l[$p['id_parameter']] ?? null; $tb .= '<td class="c">' . ($d ? '<span class="cell-heat num" style="' . heat_style($d['skor'], $p['id_parameter']) . '" title="' . e('Skor ' . $d['skor'] . ', nilai ' . nfa($d['nilai']) . ' ' . $p['satuan']) . '">' . ($mode === 'nilai' ? nfa($d['nilai']) : $d['skor']) . '</span>' : '<span class="faint">–</span>') . '</td>'; } $tb .= '<td class="c">' . ($inf ? tingkat_tag($inf['tingkat']) . '<span class="sub num">' . nf($inf['skor'], 2) . '</span>' : '–') . '</td></tr>'; }
    return ['title' => 'Matriks Data', 'html' => page_head('Matriks Data', 'Nilai dan skor tiap parameter pada setiap wilayah, sebagai dasar penelusuran hasil klasifikasi.', $acts) . '<div class="panel tight"><div class="tbl-wrap"><table class="tbl"><thead><tr>' . $th . '</tr></thead><tbody>' . $tb . '</tbody></table></div></div><p class="faint" style="font-size:13px;margin-top:12px">Warna sel menunjukkan kontribusi skor terhadap kerawanan: hijau rendah, kuning sedang, merah tinggi.</p>'];
}

/* ---------------- Data oseanografi ---------------- */
function osea_columns(): array {
    return [['k' => 'w', 'l' => 'Waktu', 'v' => fn($r) => $r['waktu'], 'f' => fn($r) => '<b>' . fmt_dt($r['waktu']) . '</b>'], ['k' => 'p', 'l' => 'Pasang surut (m)', 'cls' => 'r', 'v' => fn($r) => $r['pasut_m'], 'f' => fn($r) => '<span class="num">' . nf($r['pasut_m'], 2) . '</span>'], ['k' => 'g', 'l' => 'Gelombang (m)', 'cls' => 'r', 'v' => fn($r) => $r['gelombang_m'], 'f' => fn($r) => '<span class="num">' . nf($r['gelombang_m'], 2) . '</span>'], ['k' => 'a', 'l' => 'Angin (knot)', 'cls' => 'r', 'v' => fn($r) => $r['angin_knot'], 'f' => fn($r) => '<span class="num">' . nf($r['angin_knot'], 1) . '</span>'], ['k' => 'r', 'l' => 'Arus (m/s)', 'cls' => 'r', 'v' => fn($r) => $r['arus_ms'], 'f' => fn($r) => '<span class="num">' . nf($r['arus_ms'], 2) . '</span>'], ['k' => 'j', 'l' => 'Jenis', 'v' => fn($r) => $r['jenis_data'], 'f' => fn($r) => jenis_tag($r['jenis_data'])], ['k' => 's', 'l' => 'Sumber', 'cls' => 'wrap', 'f' => fn($r) => '<span class="muted">' . e(label_of('sumber_data', $r['id_sumber'])) . '</span>']];
}
function osea_cfg(): array {
    return ['id' => 'os', 'table' => 'data_oseanografi', 'page' => 'oseanografi', 'noun' => 'data oseanografi', 'add_label' => 'Tambah data', 'wide' => true, 'columns' => osea_columns(), 'sort' => ['k' => 'w', 'dir' => -1], 'pageSize' => 12, 'search' => fn($r) => label_of('sumber_data', $r['id_sumber']) . ' ' . $r['waktu'], 'search_ph' => 'Cari sumber',
        'filters' => [['k' => 'j', 'l' => 'Jenis data', 'opts' => [['observasi', 'Observasi'], ['prediksi', 'Prediksi'], ['simulasi', 'Simulasi']], 'test' => fn($r, $v) => $r['jenis_data'] === $v]],
        'form' => ['waktu', 'jenis_data', 'pasut_m', 'gelombang_m', 'angin_knot', 'arus_ms', 'id_sumber'], 'defaults' => fn() => ['waktu' => db_dt(), 'jenis_data' => 'observasi', 'id_sumber' => first_sumber()]];
}
function first_sumber(): ?int { foreach (tbl('sumber_data') as $s) if (stripos($s['nama_sumber'], 'simulasi') !== false) return $s['id_sumber']; return tbl('sumber_data')[0]['id_sumber'] ?? null; }
function pg_oseanografi(): array {
    if (user_role() === 'admin') return oseanografi_admin();
    osea_sinkron(); $key = array_key_exists((string) gv('ser'), OSEA_SER) ? (string) gv('ser') : 'pasut_m'; $all = tbl('data_oseanografi');
    if (gv('unduh') === 'csv') { $rows = [['Waktu', 'Pasang surut (m)', 'Gelombang (m)', 'Angin (knot)', 'Arus (m/s)', 'Jenis data', 'Sumber']]; $s = $all; usort($s, fn($a, $b) => strcmp($a['waktu'], $b['waktu'])); foreach ($s as $r) $rows[] = [$r['waktu'], $r['pasut_m'], $r['gelombang_m'], $r['angin_knot'], $r['arus_ms'], $r['jenis_data'], label_of('sumber_data', $r['id_sumber'])]; send_csv('data-oseanografi.csv', $rows); }
    $st = ''; foreach (OSEA_SER as $k => $v) { $x = array_column($all, $k); $st .= '<tr><td><b>' . $v[0] . '</b><span class="sub">' . $v[1] . '</span></td><td class="r num">' . ($x ? nf(min($x), 2) : '–') . '</td><td class="r num">' . ($x ? nf(array_sum($x) / count($x), 2) : '–') . '</td><td class="r num">' . ($x ? nf(max($x), 2) : '–') . '</td></tr>'; }
    $segs = seg(array_map(fn($k, $v) => [$k, $v[0]], array_keys(OSEA_SER), OSEA_SER), $key, fn($k) => url('oseanografi', ['ser' => $k]), 'Variabel');
    return ['title' => 'Data Oseanografi', 'html' => page_head('Data Oseanografi', 'Deret waktu pasang surut, gelombang, angin, dan arus. Data pada prototipe ini adalah simulasi untuk pengembangan.', '<a class="btn" href="' . e(url('oseanografi', ['unduh' => 'csv'])) . '">' . ic('download', 18) . 'Unduh CSV</a>') . '<div class="grid g-side" style="margin-bottom:18px"><div class="panel"><div class="panel-h"><h2>Grafik</h2>' . $segs . '</div>' . osea_chart($key, -24, 48) . '</div><div class="panel"><div class="panel-h"><h2>Statistik deskriptif</h2></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Variabel</th><th class="r">Min</th><th class="r">Rata-rata</th><th class="r">Maks</th></tr></thead><tbody>' . $st . '</tbody></table></div><p class="faint" style="font-size:13px;margin-top:10px">Berdasarkan ' . nf(count($all)) . ' pengamatan.</p></div></div>' . table_list(osea_cfg())];
}

/* ---------------- Hasil kerawanan ---------------- */
function breakdown_html(int $idW): string {
    $c = compute_skor($idW); if (!$c) return empty_state('Data belum cukup', 'Wilayah ini belum memiliki data parameter berbobot.', 'db');
    $w = array_values(array_filter($c['detail'], fn($d) => $d['bobot'] > 0)); $sb = sum(array_column($w, 'bobot')); $sk = sum(array_column($w, 'kontribusi'));
    $rows = ''; foreach ($c['detail'] as $d) $rows .= '<tr style="' . ($d['bobot'] ? '' : 'opacity:.6') . '"><td><b>' . e($d['p']['nama_parameter']) . '</b><span class="sub">' . e($d['p']['kelompok']) . ($d['bobot'] ? '' : ', pendukung') . '</span></td><td class="r num">' . nfa($d['nilai']) . ' ' . e($d['p']['satuan']) . '</td><td class="c"><span class="cell-heat num" style="' . heat_style($d['skor'], $d['p']['id_parameter']) . ';min-width:34px;height:26px">' . ($d['skor'] ?? '–') . '</span></td><td class="r num">' . nf($d['bobot'], 2) . '</td><td class="r num"><b>' . ($d['bobot'] ? nf($d['kontribusi'], 2) : '–') . '</b></td></tr>';
    return '<div class="stack" style="gap:14px"><div><div class="lbl">Skor total</div>' . scale_html($c['skor']) . '</div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Parameter</th><th class="r">Nilai</th><th class="c">Skor</th><th class="r">Bobot</th><th class="r">Bobot × skor</th></tr></thead><tbody>' . $rows . '</tbody><tfoot><tr><td colspan="3" style="padding:11px 14px"><b>Jumlah</b></td><td class="r num" style="padding:11px 14px"><b>' . nf($sb, 2) . '</b></td><td class="r num" style="padding:11px 14px"><b>' . nf($sk, 2) . '</b></td></tr></tfoot></table></div><p class="muted" style="font-size:14px">Skor total = ' . nf($sk, 2) . ' ÷ ' . nf($sb, 2) . ' = <b class="num">' . nf($c['skor'], 2) . '</b>, termasuk tingkat ' . tingkat_tag($c['tingkat']) . '</p>' . ($c['missing'] ? note_box('Parameter berbobot yang belum memiliki data: ' . e(implode(', ', array_column($c['missing'], 'nama_parameter'))) . '. Skor dihitung dari parameter yang tersedia.', 'warn', 'alert') : '') . '</div>';
}
function pg_hasil(): array {
    if (gv('detail') && ($w = row('wilayah', (int) gv('detail')))) {
        $hist = where('hasil_kerawanan', fn($h) => $h['id_wilayah'] === $w['id_wilayah']); usort($hist, fn($a, $b) => [$b['tanggal_analisis'], $b['id_hasil']] <=> [$a['tanggal_analisis'], $a['id_hasil']]);
        $hl = implode('', array_map(fn($h) => '<div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center"><span>' . fmt_d($h['tanggal_analisis']) . '<span class="faint"> ' . e($h['metode']) . '</span></span><span style="display:flex;gap:10px;align-items:center"><b class="num">' . nf($h['skor_total'], 2) . '</b>' . tingkat_tag(row('tingkat_kerawanan', $h['id_tingkat'])) . '</span></div>', $hist));
        return ['title' => 'Hasil Kerawanan', 'html' => page_head('Rincian: ' . $w['nama_wilayah'], 'Penelusuran perhitungan skor kerawanan.', '<a class="btn" href="' . e(url('hasil')) . '">' . ic('chevr', 16) . 'Kembali</a>') . '<div class="panel">' . breakdown_html($w['id_wilayah']) . '<div class="hr"></div><div class="lbl" style="margin-bottom:8px">Riwayat analisis</div><div class="list">' . $hl . '</div></div>'];
    }
    if (gv('unduh') === 'csv') { $rows = [['Wilayah', 'Tipe', 'Skor total', 'Tingkat', 'Metode', 'Tanggal analisis']]; foreach (wil_rows() as $r) if ($r['inf']) $rows[] = [$r['w']['nama_wilayah'], $r['w']['tipe'], $r['inf']['skor'], $r['inf']['tingkat']['nama_tingkat'], $r['inf']['hasil']['metode'], $r['inf']['hasil']['tanggal_analisis']]; send_csv('hasil-kerawanan.csv', $rows); }
    $cfg = ['id' => 'hs', 'page' => 'hasil', 'readonly' => true, 'rows' => fn() => array_values(array_filter(wil_rows(), fn($r) => $r['inf'])), 'sort' => ['k' => 's', 'dir' => -1], 'pageSize' => 10, 'search' => fn($r) => $r['w']['nama_wilayah'], 'search_ph' => 'Cari wilayah',
        'filters' => [['k' => 't', 'l' => 'Tingkat', 'opts' => array_map(fn($t) => [$t['id_tingkat'], $t['nama_tingkat']], tingkat_list()), 'test' => fn($r, $v) => (string) $r['inf']['tingkat']['id_tingkat'] === $v]],
        'row_actions' => fn($r) => '<a class="btn btn-sm" href="' . e(url('hasil', ['detail' => $r['w']['id_wilayah']])) . '">Rincian</a>',
        'columns' => [['k' => 'w', 'l' => 'Wilayah', 'v' => fn($r) => $r['w']['nama_wilayah'], 'f' => fn($r) => '<b>' . e($r['w']['nama_wilayah']) . '</b><span class="sub">' . e($r['w']['tipe']) . '</span>'], ['k' => 's', 'l' => 'Skor total', 'v' => fn($r) => $r['inf']['skor'], 'f' => fn($r) => skor_bar((float) $r['inf']['skor'], $r['inf']['tingkat']['warna'] ?? null)], ['k' => 't', 'l' => 'Tingkat', 'v' => fn($r) => $r['inf']['skor'], 'f' => fn($r) => tingkat_tag($r['inf']['tingkat'])], ['k' => 'm', 'l' => 'Metode', 'cls' => 'wrap', 'v' => fn($r) => $r['inf']['hasil']['metode'], 'f' => fn($r) => e($r['inf']['hasil']['metode'])], ['k' => 'd', 'l' => 'Tanggal analisis', 'v' => fn($r) => $r['inf']['hasil']['tanggal_analisis'], 'f' => fn($r) => fmt_d($r['inf']['hasil']['tanggal_analisis'])]]];
    return ['title' => 'Hasil Kerawanan', 'html' => page_head('Hasil Kerawanan', 'Skor dan tingkat kerawanan terbaru tiap wilayah. Pilih rincian untuk menelusuri perhitungannya.', '<a class="btn" href="' . e(url('hasil', ['unduh' => 'csv'])) . '">' . ic('download', 18) . 'Unduh CSV</a>') . table_list($cfg)];
}

/* ---------------- Simulasi skor ---------------- */
function pg_simulasi(): array {
    $ws = tbl('wilayah'); $sel = (int) gv('w') ?: ($ws[0]['id_wilayah'] ?? 0); $l = latest_data($sel); $reset = gv('reset') !== null; $v = is_array(gv('v')) && !$reset ? $_GET['v'] : []; $ps = array_values(array_filter(tbl('parameter'), fn($p) => $p['bobot'] > 0 || isset($l[$p['id_parameter']])));
    $ov = []; foreach ($ps as $p) { $raw = $v[$p['id_parameter']] ?? ''; if ($raw !== '' && is_numeric($raw)) $ov[$p['id_parameter']] = (float) $raw; }
    $c = compute_skor($sel, $ov); $base = info_wilayah($sel);
    $inputs = ''; foreach ($ps as $p) { $baseV = $l[$p['id_parameter']]['nilai'] ?? ''; $cur = $ov[$p['id_parameter']] ?? $baseV; $d = $c ? array_values(array_filter($c['detail'], fn($x) => $x['p']['id_parameter'] === $p['id_parameter']))[0] ?? null : null; $inputs .= '<div class="field"><label for="sp' . $p['id_parameter'] . '">' . e($p['nama_parameter']) . ' <span class="faint">(' . e($p['satuan']) . ($p['bobot'] ? ', bobot ' . nf($p['bobot'] * 100, 0) . '%' : ', pendukung') . ')</span></label><input class="input num" id="sp' . $p['id_parameter'] . '" name="v[' . $p['id_parameter'] . ']" type="number" step="any" value="' . e($cur) . '">' . ($d ? '<div class="hint">Skor ' . $d['skor'] . '</div>' : '') . '</div>'; }
    $res = $c ? '<div class="panel-h"><h2>Hasil simulasi</h2></div><div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap"><div><div class="num" style="font-family:var(--font-display);font-size:44px;font-weight:600;line-height:1">' . nf($c['skor'], 2) . '</div><div class="muted">Skor total</div></div>' . tingkat_tag($c['tingkat'], true) . '</div>' . scale_html($c['skor']) . '<div class="lvl-card" style="--c:' . e($c['tingkat']['warna']) . '">' . lvl_icon(rank_of($c['tingkat']['id_tingkat']), 20) . '<b>' . e($c['tingkat']['nama_tingkat']) . '</b><p>' . e($c['tingkat']['makna_warga']) . '</p></div>' . ($base ? '<div class="hr"></div><dl class="kv"><dt>Hasil analisis tersimpan</dt><dd>' . nf($base['skor'], 2) . ' (' . e($base['tingkat']['nama_tingkat']) . ')</dd><dt>Selisih</dt><dd class="num">' . ($c['skor'] - $base['skor'] >= 0 ? '+' : '') . nf($c['skor'] - $base['skor'], 2) . '</dd></dl>' : '') : empty_state('Isi nilai parameter', 'Masukkan nilai pada minimal satu parameter berbobot.', 'flask');
    $h = page_head('Simulasi Skor', 'Ubah nilai parameter untuk melihat dampaknya pada skor dan tingkat kerawanan. Simulasi tidak mengubah data sistem.', '<a class="btn" href="' . e(url('simulasi', ['w' => $sel, 'reset' => 1])) . '">' . ic('refresh', 18) . 'Kembalikan ke data wilayah</a>')
        . '<div class="grid g-side"><div class="panel"><form method="get" action="index.php"><input type="hidden" name="p" value="simulasi"><div class="field" style="max-width:420px"><label for="sim-w">Wilayah dasar</label><div style="display:flex;gap:8px"><select class="select" id="sim-w" name="w">' . implode('', array_map(fn($x) => '<option value="' . $x['id_wilayah'] . '"' . ($x['id_wilayah'] === $sel ? ' selected' : '') . '>' . e($x['nama_wilayah']) . '</option>', $ws)) . '</select></div><div class="hint">Mengganti wilayah memuat ulang nilai dasarnya.</div></div><div class="row2">' . $inputs . '</div><button class="btn btn-primary" type="submit">' . ic('play', 18) . 'Hitung simulasi</button></form></div><div class="panel" style="align-self:start;position:sticky;top:84px">' . $res . '</div></div>';
    return ['title' => 'Simulasi Skor', 'html' => $h];
}
